(()=>{'use strict';if(window.__qpuSideList)return;window.__qpuSideList=true;let loading=false;const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:[];async function populate(){const root=document.querySelector('.am-split[data-am-screen="purchase"]');if(!root||root.dataset.qpuListReady||loading)return;loading=true;try{const res=await fetch('/api/purchase-orders',{credentials:'include',cache:'no-store'}),payload=await res.json();if(!res.ok||payload.success===false)throw Error(payload.message||'조회 실패');if(!root.isConnected)return;const data=rows(payload),list=root.querySelector('.am-list-items'),title=root.querySelector('.am-list-title span'),count=root.querySelector('.am-list-count'),search=root.querySelector('.am-list-search');if(!list)return;root.dataset.qpuListReady='1';if(title)title.textContent=data.length+'건';if(count)count.textContent=data.length+'건 구매발주';list.replaceChildren();const labelCells=[...root.querySelectorAll('td,th,label')];labelCells.forEach(el=>{if(el.children.length===0&&el.textContent.trim()==='요청입고')el.textContent='현재 입고일자';if(el.children.length===0&&el.textContent.trim()==='수량')el.textContent='수량(kg)'});const btns=[];data.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.className='am-list-item';const t=document.createElement('b');t.textContent=p.purchaseNo||p.no||'발주 '+(i+1);const sub=document.createElement('span');sub.textContent=[p.supplier,p.item||p.material].filter(Boolean).join(' · ');b.append(t,sub);b.addEventListener('click',()=>{btns.forEach(x=>x.classList.toggle('active',x===b));const note=root.querySelector('.am-detail-note');if(note)note.textContent='선택한 구매발주: '+t.textContent;root.querySelector('#qpu-selected-record')?.remove();const form=root.querySelector('.am-detail-note')?.previousElementSibling||root;const inputs=[...root.querySelectorAll('input,select,textarea')].filter(el=>!el.closest('.am-list-items,.qpu-side-pagination')&&!el.classList.contains('am-list-search'));const labelOf=el=>{const tr=el.closest('tr');if(tr){const cells=[...tr.children];const i=cells.findIndex(c=>c.contains(el));return i>0?cells[i-1].textContent.trim():''}return el.closest('label')?.textContent.trim()||el.parentElement?.previousElementSibling?.textContent.trim()||''};const find=label=>inputs.find(el=>labelOf(el)===label||(label==='수량'&&labelOf(el)==='수량(kg)'));const set=(label,value)=>{const el=find(label);if(!el)return;const v=String(value??'');if(el.tagName==='SELECT'&&!Array.from(el.options).some(o=>o.value===v||o.textContent.trim()===v))return;el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};const fromNumber=String(p.purchaseNo||p.no||'').match(/^(20\d{2}-\d{2}-\d{2})-\d+$/);const date=String(p.requestedDueDate||p.due||p.receiptDate||fromNumber?.[1]||'').slice(0,10);let orderDate=String(p.orderDate||p.order_date||'').slice(0,10);if(!orderDate&&/^20\d{2}-\d\d-\d\d$/.test(date)){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-7);orderDate=d.toISOString().slice(0,10)}set('발주일자',orderDate);set('공급업체',p.supplier||p.vendor);set('품목명',String(p.item||p.material||'').replace(/\s*\[kg\]\s*/gi,'').trim());set('수량',p.qty??p.quantity??0);set('요청입고',date);const status=/입고완료|완료/.test(String(p.receiptStatus||p.status||''))?'완료':String(p.status||p.approvalStatus||'대기');const statusEl=find('발주상태');if(statusEl&&statusEl.tagName==='SELECT'&&!Array.from(statusEl.options).some(o=>o.value==='완료')){const o=document.createElement('option');o.value='완료';o.textContent='완료';statusEl.append(o)}set('발주상태','완료');const iqcEl=find('IQC');if(iqcEl?.tagName==='SELECT'&&!Array.from(iqcEl.options).some(o=>o.value==='완료')){const option=document.createElement('option');option.value='완료';option.textContent='완료';iqcEl.append(option)}set('IQC','완료');set('비고',p.notes||'');const due=find('요청입고');if(due){const cell=due.closest('tr')?.querySelector('td:first-child,th:first-child');if(cell&&cell.textContent.trim()==='요청입고')cell.textContent='현재 입고일자'}const oldExtra=root.querySelector('#qpu-selected-record');oldExtra?.remove();const title=root.querySelector('.am-detail-note');if(title)title.textContent='선택한 기존 발주: '+t.textContent+' (조회 전용 · 저장하지 않음)';});list.append(b);btns.push(b)});let page=1;const pager=document.createElement('div');pager.className='qpu-side-pagination';pager.style.cssText='display:flex;justify-content:center;gap:5px;padding:8px';list.after(pager);function draw(){const q=(search?.value||'').trim().toLowerCase(),matched=btns.filter(b=>b.textContent.toLowerCase().includes(q)),total=Math.max(1,Math.ceil(matched.length/10));page=Math.min(page,total);btns.forEach(b=>{b.hidden=true;b.style.display='none'});matched.slice((page-1)*10,page*10).forEach(b=>{b.hidden=false;b.style.display='flex'});pager.replaceChildren();for(let i=1;i<=total;i++){const b=document.createElement('button');b.type='button';b.textContent=i;b.style.cssText='padding:4px 8px;border:1px solid #d1dce8;border-radius:4px;background:'+(i===page?'#2d73db;color:white':'white');b.onclick=()=>{page=i;draw()};pager.append(b)}}search?.addEventListener('input',()=>{page=1;draw()});draw()}catch(e){const list=root.querySelector('.am-list-items');if(list)list.textContent='기존 발주 목록 조회 실패: '+e.message}finally{loading=false}}new MutationObserver(()=>{if(document.querySelector('.am-split[data-am-screen="purchase"]:not([data-qpu-list-ready])'))populate()}).observe(document.body,{childList:true,subtree:true});
// Supplier chooser limited to the purchase basic-settings supplier field.
function supplierField(root){
 const inputs=[...root.querySelectorAll('input')];
 return inputs.find(el=>{
  const tr=el.closest('tr');if(!tr)return false;
  const cell=el.closest('td');const prev=cell?.previousElementSibling;
  return prev?.textContent.trim()==='공급업체';
 });
}
let popup;
function openSupplier(root,input){
 if(popup)popup.remove();
 popup=document.createElement('div');popup.className='qpu-supplier-dialog';
 popup.style.cssText='position:fixed;z-index:100000;width:310px;max-width:calc(100vw - 20px);background:#fff;border:1px solid #b9cadd;border-radius:7px;box-shadow:0 12px 32px #17365340;padding:8px;font-size:13px';
 const r=input.getBoundingClientRect();popup.style.left=Math.max(8,Math.min(window.innerWidth-320,r.left))+'px';popup.style.top=Math.max(8,Math.min(window.innerHeight-360,r.bottom+4))+'px';
 const search=document.createElement('input');search.placeholder='공급업체 검색';search.style.cssText='width:100%;padding:8px;border:1px solid #ccd8e8;box-sizing:border-box';
 const list=document.createElement('div');list.style.cssText='max-height:220px;overflow:auto;margin:6px 0;border:1px solid #e0e7f0';
 const foot=document.createElement('div');foot.style.cssText='display:flex;gap:5px;justify-content:flex-end';
 const selections=new Set(input.value?input.value.split(',').map(x=>x.trim()).filter(Boolean):[]);
 const names=[...new Set([...root.querySelectorAll('.am-list-item span')].map(el=>el.textContent.split(' · ')[0].trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));
 const render=()=>{list.replaceChildren();const choices=['전체',...names.filter(n=>n.toLowerCase().includes(search.value.trim().toLowerCase()))];for(const name of choices){const label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:7px;padding:7px;border-bottom:1px solid #eef2f6;cursor:pointer';const cb=document.createElement('input');cb.type='checkbox';cb.checked=name==='전체'?selections.size===names.length:names.includes(name)&&selections.has(name);cb.onchange=()=>{if(name==='전체'){selections.clear();if(cb.checked)names.forEach(n=>selections.add(n))}else{if(cb.checked)selections.add(name);else selections.delete(name)}render()};label.append(cb,document.createTextNode(name));list.append(label)}};
 search.oninput=render;render();
 for(const [name,fn] of [['추가',()=>{search.value='';render();search.focus()}],['수정',()=>{search.focus()}],['삭제',()=>{selections.clear();render()}],['취소',()=>popup.remove()],['확인',()=>{input.value=[...selections].join(', ');input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));popup.remove()}]]){const btn=document.createElement('button');btn.type='button';btn.textContent=name;btn.style.cssText='padding:5px 8px;background:#fff;border:1px solid #cbd6e4;border-radius:4px;cursor:pointer';btn.onclick=fn;foot.append(btn)}
 popup.append(search,list,foot);document.body.append(popup);search.focus();
}
document.addEventListener('click',event=>{
 const root=document.querySelector('.am-split[data-am-screen="purchase"]');if(!root)return;
 const input=supplierField(root);
 if(input&&(event.target===input)){event.preventDefault();event.stopPropagation();openSupplier(root,input)}
},true);
populate()})();